package me.pikanote.companion;
import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import javax.net.ssl.HttpsURLConnection;
/** Read-only Gmail tool using the owner's encrypted settings cache. */
final class PhoneMail{
 static JSONObject config(Store s)throws Exception{PikaService service=PikaService.instance;if(service!=null&&service.ble.online&&!service.ble.deviceBusy&&!service.syncing){try{BleTransport.Reply reply=service.ble.rpc("/api/phone/settings-export","GET",null,null);if(reply.status==200)synchronized(s){s.state.put("deviceSecrets",reply.json());s.save();}}catch(Exception ignored){}}synchronized(s){JSONObject secrets=s.state.optJSONObject("deviceSecrets"),spaces=secrets==null?null:secrets.optJSONObject("namespaces"),mail=spaces==null?null:spaces.optJSONObject("pikaMail"),entry=mail==null?null:mail.optJSONObject("config");if(entry==null)throw new IOException("Connect Pika once to copy Gmail settings to the phone");return new JSONObject(entry.optString("value","{}"));}}
 static JSONObject json(String url,String method,String token,String body)throws Exception{HttpsURLConnection c=(HttpsURLConnection)new URL(url).openConnection();try{c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setRequestMethod(method);if(!token.isEmpty())c.setRequestProperty("Authorization","Bearer "+token);if(body!=null){c.setRequestProperty("Content-Type","application/x-www-form-urlencoded");c.setDoOutput(true);byte[] bytes=body.getBytes(StandardCharsets.UTF_8);c.setFixedLengthStreamingMode(bytes.length);try(OutputStream out=c.getOutputStream()){out.write(bytes);}}int status=c.getResponseCode();if(status!=200)throw new IOException("Gmail read HTTP "+status);ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){PhoneBackup.copyBounded(in,out,1048576);}return new JSONObject(out.toString("UTF-8"));}finally{c.disconnect();}}
 static String encode(String s)throws Exception{return URLEncoder.encode(s,"UTF-8");}
 static String text(JSONObject part){String mime=part.optString("mimeType"),result="";JSONObject body=part.optJSONObject("body");if(body!=null&&!body.optString("data").isEmpty()&&(mime.equals("text/plain")||mime.equals("text/html"))){try{result=new String(android.util.Base64.decode(body.getString("data"),android.util.Base64.URL_SAFE|android.util.Base64.NO_WRAP),StandardCharsets.UTF_8);if(mime.equals("text/html"))result=android.text.Html.fromHtml(result,0).toString();}catch(Exception ignored){}}JSONArray parts=part.optJSONArray("parts");if(result.isEmpty()&&parts!=null){for(int n=0;n<parts.length();n++){JSONObject child=parts.optJSONObject(n);if(child!=null&&child.optString("mimeType").equals("text/plain")){result=text(child);break;}}if(result.isEmpty())for(int n=0;n<parts.length();n++){JSONObject child=parts.optJSONObject(n);if(child!=null){result=text(child);if(!result.isEmpty())break;}}}return result;}
 static JSONObject read(Store s)throws Exception{JSONObject cfg=config(s);String client=cfg.optString("clientId"),refresh=cfg.optString("refreshToken");if(client.isEmpty()||refresh.isEmpty())throw new IOException("Gmail is not configured");String body="grant_type=refresh_token&client_id="+encode(client)+"&refresh_token="+encode(refresh);if(!cfg.optString("clientSecret").isEmpty())body+="&client_secret="+encode(cfg.getString("clientSecret"));String token=json("https://oauth2.googleapis.com/token","POST","",body).getString("access_token");JSONArray filters=cfg.optJSONArray("senders");int count=filters==null?0:Math.min(4,filters.length()),quota=count==0?4:Math.max(1,4/count);List<JSONObject> messages=new ArrayList<>();Set<String> threads=new HashSet<>();for(int group=0;group<Math.max(1,count);group++){String query="in:inbox category:primary is:unread newer_than:7d";if(count>0&&!filters.optString(group).trim().isEmpty())query+=" from:("+filters.optString(group).trim()+")";JSONObject list=json("https://gmail.googleapis.com/gmail/v1/users/me/messages?maxResults="+(quota*3)+"&q="+encode(query),"GET",token,null);JSONArray ids=list.optJSONArray("messages");int added=0;if(ids==null)continue;for(int n=0;n<ids.length()&&added<quota;n++){JSONObject id=ids.getJSONObject(n);if(threads.contains(id.optString("threadId")))continue;JSONObject item=json("https://gmail.googleapis.com/gmail/v1/users/me/messages/"+encode(id.getString("id"))+"?format=full","GET",token,null);JSONObject payload=item.getJSONObject("payload");String from="",subject="";JSONArray headers=payload.optJSONArray("headers");if(headers!=null)for(int h=0;h<headers.length();h++){JSONObject header=headers.getJSONObject(h);if(header.optString("name").equalsIgnoreCase("From"))from=header.optString("value");if(header.optString("name").equalsIgnoreCase("Subject"))subject=header.optString("value");}String content=text(payload).replaceAll("https?://[^\\s<>]+","[ссылка]");if(content.length()>6000)content=content.substring(0,6000);messages.add(new JSONObject().put("id",item.getString("id")).put("from",from).put("subject",subject).put("body",content.isEmpty()?item.optString("snippet"):content).put("received",item.optLong("internalDate")));threads.add(item.optString("threadId"));added++;}}
 messages.sort((a,b)->Long.compare(b.optLong("received"),a.optLong("received")));JSONArray out=new JSONArray();for(JSONObject item:messages){if(out.length()>=4)break;item.remove("received");out.put(item);}return new JSONObject().put("readOnly",true).put("messages",out).put("asOf",java.time.Instant.now().toString());}
}
